import { Component, OnInit, ViewChild } from '@angular/core';
import { GovBrTabModule, TabComponent, GovBrDatePickerModule } from '@serpro/ngx-dsgovbr';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ConsultarClassificacoesTributariasCbsIbsComponent } from "./consultar-classificacoes-tributarias-cbs-ibs/consultar-classificacoes-tributarias-cbs-ibs.component";
import { ConsultarClassificacoesTributariasImpostoSeletivoComponent } from "./consultar-classificacoes-tributarias-imposto-seletivo/consultar-classificacoes-tributarias-imposto-seletivo.component";
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { Router } from '@angular/router';
import { MensagemService } from '../../services/mensagem.service';
import { DispositivoService } from '../../services/dispositivo.service';
import { Subscription } from 'rxjs/internal/Subscription';

@Component({
  selector: 'consultar-classificacoes-tributarias',
  templateUrl: './consultar-classificacoes-tributarias.component.html',
  styleUrl: './consultar-classificacoes-tributarias.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrTabModule,
    GovBrDatePickerModule,
    ConsultarClassificacoesTributariasCbsIbsComponent,
    ConsultarClassificacoesTributariasImpostoSeletivoComponent,
    MyTitleComponent,
  ],
  providers: [],
})
export class ConsultarClassificacoesTributariasComponent implements OnInit {

  form!: FormGroup;
  dataConsulta: Date | null = null;

  @ViewChild(ConsultarClassificacoesTributariasCbsIbsComponent)
  cbsIbsComponent!: ConsultarClassificacoesTributariasCbsIbsComponent;

  @ViewChild(ConsultarClassificacoesTributariasImpostoSeletivoComponent)
  impostoSeletivoComponent!: ConsultarClassificacoesTributariasImpostoSeletivoComponent;

  @ViewChild('brTabCbsIbs') brTabCbsIbs!: TabComponent;
  @ViewChild('brTabImpostoSeletivo') brTabImpostoSeletivo!: TabComponent;

  private subscriptions: Subscription = new Subscription();
  dispositivo: string = '';

  constructor(
    private formBuilder: FormBuilder,
    private router: Router,
    private mensagemService: MensagemService,
    private dispositivoService: DispositivoService,
  ) { }

  ngOnInit(): void {
    this.form = this.formBuilder.group({
      dataControl: [new Date(), [Validators.required]],
    });
    this.setSubscriptions();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.mensagemService.limpar();
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo: any) => {
        this.dispositivo = dispositivo;
        if (this.dispositivo === 'device-xsmall') {

        } else {

        }
      }));
  }

  submit(event: any) {
    this.mensagemService.limpar();
    if (!this.form.valid) {
      this.mensagemService.mostrar('Erro', 'Erro', 'Por favor, preencha corretamente o formulário antes de consultar.');
      return;
    }

    this.dataConsulta = this.form.get('dataControl')?.value;

    // Aciona a consulta no componente filho ativo
    if (this.cbsIbsComponent && this.brTabCbsIbs.active) {
      this.cbsIbsComponent.consultar(this.dataConsulta);
    }
    if (this.impostoSeletivoComponent && this.brTabImpostoSeletivo.active) {
      this.impostoSeletivoComponent.consultar(this.dataConsulta);
    }
  }

  onTabActiveChange(tab: TabComponent) {

  }

  voltar() {
    this.router.navigate(['/calculadora']);
  }

}
